// === Tab: mySketch.js ===
//ASCII shader simulating a retro terminal displaying an old skool demo effect of a sphere orbiting a cube
//Potential #WCCChallenge "Retro", "ASCII", "Orbit" 30th August 2026 to 6th September 2026

let asciiShader;
let sceneGfx;
let fontAtlas;

// Characters sorted by visual density (empty → dense)
const CHARS = " .,:;+*?%S#@";
const CELL_SIZE = 8; // pixels per character cell. 8 is minimum.



// Using p5js2 so need to have setup as async and await the shader loading

async function setup() {
  createCanvas(800, 600, WEBGL);
  pixelDensity(1);

  // off-screen buffer for the 3D scene
  sceneGfx = createGraphics(width, height, WEBGL);
  sceneGfx.pixelDensity(1);

  // build a 1-row texture with every ASCII glyph
  fontAtlas = buildFontAtlas();

  asciiShader = await loadShader('https://openprocessing.org/sketch/2997770/files/shader.vert', 'shader.frag');
}

/* ---- build a horizontal strip of glyphs ---- */
function buildFontAtlas() {
  const n    = CHARS.length;
  const size = 32;                         // render glyphs at 32 px (oversampled)
  let pg = createGraphics(size * n, size);
  pg.pixelDensity(1);
  pg.background(0);
  pg.fill(255);
  pg.noStroke();
  pg.textFont('Courier New, Courier, monospace');
  pg.textSize(size * 0.85);
  pg.textAlign(CENTER, CENTER);
  for (let i = 0; i < n; i++) {
    pg.text(CHARS[i], i * size + size / 2, size / 2);
  }
  return pg;
}


function draw() {

	let t = millis()/1000;

  //  draw the 3D scene into the buffer 
  sceneGfx.background(0);

  sceneGfx.push();
  sceneGfx.ambientLight(80);
  sceneGfx.directionalLight(255, 255, 255, 0.5, 0.5, -1);
  sceneGfx.pointLight(255, 180, 100, 200, -200, 300);

  // spinning cube
  sceneGfx.push();
  sceneGfx.rotateX(frameCount * 0.018);
  sceneGfx.rotateY(frameCount * 0.013);
  sceneGfx.specularMaterial(160, 180, 255);
  sceneGfx.shininess(255);
  sceneGfx.box(130*sin(t/10));
  sceneGfx.pop();

  // orbiting sphere
  sceneGfx.push();
  sceneGfx.rotateY(frameCount * 0.03);
  sceneGfx.translate(230, 0, 0);
  sceneGfx.specularMaterial(255, 120, 130);
  sceneGfx.sphere(28);
  sceneGfx.pop();

  sceneGfx.pop();

  //  apply the ASCII post-process shader 
  shader(asciiShader);
  asciiShader.setUniform('u_scene',      sceneGfx);
  asciiShader.setUniform('u_font',       fontAtlas);
  asciiShader.setUniform('u_resolution', [width, height]);
  asciiShader.setUniform('u_cellSize',   CELL_SIZE);
  asciiShader.setUniform('u_numChars',   CHARS.length);

  noStroke();
  rect(0, 0, width, height);           
  filter(BLUR,1); // for retro terminal look
}

// === Tab: shader.vert ===
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}

// === Tab: shader.frag ===

precision highp float;

varying vec2 vTexCoord;

uniform sampler2D u_scene;     // the rendered 3D scene
uniform sampler2D u_font;      // font atlas (all chars in a row)
uniform vec2  u_resolution;    // canvas size in px
uniform float u_cellSize;      // cell size in px
uniform float u_numChars;      // how many chars in the atlas

void main() {
  vec2 uv = vTexCoord;

  // ---- grid / cell math ----
  vec2 cellSizeUV = vec2(u_cellSize) / u_resolution;
  vec2 cell       = floor(uv / cellSizeUV);        // which cell
  vec2 cellCenter = (cell + 0.5) * cellSizeUV;      // centre of cell

  // ---- sample the scene at the cell centre ----
  vec4 sceneCol = texture2D(u_scene, cellCenter);

  // perceived brightness (Rec 601 luma)
  float luma = dot(sceneCol.rgb, vec3(0.299, 0.587, 0.114));

  // ---- pick a character index from brightness ----
  float idx = floor(luma * u_numChars);
  idx = clamp(idx, 0.0, u_numChars - 1.0);

  // ---- look up that character in the font atlas ----
  vec2 posInCell = fract(uv / cellSizeUV);           // 0‑1 inside cell
  vec2 fontUV    = vec2(
    (idx + posInCell.x) / u_numChars,                // horizontal offset
    posInCell.y                                       // vertical
  );

  float charMask = texture2D(u_font, fontUV).r;      // white-on-black atlas

  //  colour modes  

  // MODE 1 — coloured ASCII (scene colour × character shape)
  //vec3 result = sceneCol.rgb * charMask;

  // MODE 2 — green terminal
   vec3 result = vec3(0.1, 1.0, 0.3) * charMask * luma;

  // MODE 3 — white on black
  // vec3 result = vec3(charMask);

  gl_FragColor = vec4(result, 1.0);
}

